use verus::prelude::*;

#[verus]
fn solve(stdin_input: Vec<char>) -> Vec<char> {
    // The input must be either 3 or 4 characters long.
    let n = stdin_input.len();
    requires(n == 3 || n == 4);
    // The middle character must be a space.
    requires(stdin_input[1] == ' ');
    // If there is a fourth character, it must be a newline.
    if n == 4 {
        requires(stdin_input[3] == '\n');
    }
    // The first and third characters must be in 'A'..='F'.
    let c1 = stdin_input[0];
    let c2 = stdin_input[2];
    requires(c1 >= 'A' && c1 <= 'F');
    requires(c2 >= 'A' && c2 <= 'F');

    // Specification of the output.
    ensures(|output: Vec<char>| {
        // Exactly two characters: the comparison symbol and a newline.
        output.len() == 2 &&
        output[1] == '\n' &&
        // The first character reflects the ordering of c1 vs. c2.
        if c1 < c2 {
            output[0] == '<'
        } else if c1 > c2 {
            output[0] == '>'
        } else {
            output[0] == '='
        }
    });

    // Compute the comparison symbol.
    let sym = if c1 < c2 {
        '<'
    } else if c1 > c2 {
        '>'
    } else {
        '='
    };

    // Build the result vector.
    let mut output: Vec<char> = Vec::new();
    output.push(sym);
    output.push('\n');
    output
}

